Tb=[np.ones_like(T),T,1/T,np.sqrt(T),T**2]
def model(th, mode):
    if mode==0: ex=np.exp(-(th[0]+th[1]/T)*eps)
    if mode==1: ex=np.exp(-(th[0]+th[1]*T)*eps)
    if mode==2: ex=np.exp(-(th[0]+th[1]*T+th[2]/T)*eps)
    cols=[]
    for i in range(3):
        for tb in Tb:
            cols.append(-eps**(i+1)*tb*ex)
    A=np.column_stack(cols)
    c,*_=np.linalg.lstsq(A,sigma,rcond=None)
    return sigma-A@c
